const express = require('express');
const path = require('path');
const fs = require('fs');
const fsPromises = fs.promises;

const DEFAULT_PORT = process.env.PORT ? Number(process.env.PORT) : 3000;
const STORAGE_FILENAME = process.env.STORAGE_PATH || path.join(__dirname, 'visits.json');

function createApp() {
  const app = express();

  app.use(express.json({ limit: '1kb' }));

  // Serve static public files
  app.use(express.static(path.join(__dirname, 'public')));

  // In-memory model
  const model = {
    id: 'visits',
    count: 0,
    lastUpdated: new Date().toISOString()
  };

  // A simple write lock for serializing file writes
  let writeLock = Promise.resolve();

  async function loadFromDisk() {
    try {
      const raw = await fsPromises.readFile(STORAGE_FILENAME, 'utf8');
      try {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed.count === 'number') {
          model.count = parsed.count;
          model.lastUpdated = parsed.lastUpdated || model.lastUpdated;
          // keep id
        }
      } catch (err) {
        console.warn('visits.json parse failed, starting fresh');
      }
    } catch (err) {
      if (err.code !== 'ENOENT') {
        console.warn('Failed to read visits.json on startup:', err && err.code);
      }
      // If file doesn't exist, start with defaults (0)
    }
  }

  async function persistToDisk() {
    // chain writes
    const doWrite = async () => {
      const payload = JSON.stringify({ id: model.id, count: model.count, lastUpdated: model.lastUpdated }, null, 2);
      const tmp = STORAGE_FILENAME + '.tmp';
      try {
        await fsPromises.writeFile(tmp, payload, { encoding: 'utf8' });
        await fsPromises.rename(tmp, STORAGE_FILENAME);
        return { ok: true };
      } catch (err) {
        // Clean up tmp if exists
        try { await fsPromises.unlink(tmp).catch(()=>{}); } catch(e){}
        console.warn('Failed to persist visits.json:', err && err.code);
        return { ok: false, error: err };
      }
    };

    const prev = writeLock;
    let release;
    writeLock = new Promise(res => release = res);
    await prev;
    try {
      const res = await doWrite();
      return res;
    } finally {
      release();
    }
  }

  // API endpoints
  app.get('/api/visit', (req, res) => {
    res.json({ count: model.count, ts: new Date().toISOString() });
  });

  app.post('/api/visit', async (req, res) => {
    // ignore body content; treat as increment request
    try {
      model.count = (typeof model.count === 'number') ? (model.count + 1) : 1;
      model.lastUpdated = new Date().toISOString();
      const persistResult = await persistToDisk();
      const response = { count: model.count, ts: model.lastUpdated };
      if (!persistResult.ok) response.warning = 'persist_failed';
      res.json(response);
    } catch (err) {
      // keep in-memory increment, but respond with warning
      console.error('Unexpected server error handling POST /api/visit');
      res.json({ count: model.count, ts: model.lastUpdated, warning: 'internal_error' });
    }
  });

  // Catch other methods on /api/visit
  app.all('/api/visit', (req, res, next) => {
    if (req.method !== 'GET' && req.method !== 'POST') {
      res.status(405).json({ error: 'Method not allowed' });
    } else next();
  });

  return { app, model, loadFromDisk };
}

function startServer(options = {}) {
  const port = options.port || DEFAULT_PORT;
  const serverName = 'node-express-starter';
  const { app, loadFromDisk } = createApp();

  const server = require('http').createServer(app);

  const listenPromise = new Promise(async (resolve, reject) => {
    try {
      await loadFromDisk();
    } catch (err) {
      console.warn('Failed during initial loadFromDisk:', err && err.code);
    }

    server.on('error', err => reject(err));
    server.listen(port, () => {
      const addr = server.address();
      const actualPort = (addr && addr.port) || port;
      resolve({ server, port: actualPort, name: serverName });
    });
  });

  return listenPromise.then(val => ({
    server: val.server,
    port: val.port,
    stop: () => new Promise((resolve, reject) => {
      val.server.close(err => err ? reject(err) : resolve());
    })
  }));
}

// If run directly, start the server and log
if (require.main === module) {
  (async () => {
    try {
      const running = await startServer({ port: DEFAULT_PORT });
      console.log(`Server listening on http://localhost:${running.port}`);
    } catch (err) {
      console.error('Failed to start server:', err && err.message);
      process.exit(1);
    }
  })();
}

module.exports = { startServer, createApp };

