// Frontend logic with guarded initialization, safe storage wrappers, delegated event handling
(function(){
  // Safe localStorage wrapper
  const safeStorage = (() => {
    let available = true;
    try {
      const key = '__storage_test__';
      window.localStorage.setItem(key, key);
      window.localStorage.removeItem(key);
    } catch (err) {
      available = false;
    }
    if (!available) {
      const mem = Object.create(null);
      return {
        getItem: (k)=> mem[k] === undefined ? null : mem[k],
        setItem: (k,v)=>{ mem[k]=String(v); },
        removeItem: (k)=>{ delete mem[k]; }
      };
    }
    return window.localStorage;
  })();

  // Optional IndexedDB probing (non-essential)
  async function tryOpenIndexedDB(){
    if (!('indexedDB' in window)) throw new Error('no-indexeddb');
    return new Promise((resolve, reject)=>{
      let opened;
      try {
        const req = indexedDB.open('node-express-starter', 1);
        req.onupgradeneeded = ()=>{
          try { req.result.createObjectStore('meta'); } catch(e){}
        };
        req.onsuccess = ()=>{ opened = req.result; resolve(opened); };
        req.onerror = ()=> reject(req.error);
      } catch(err){ reject(err); }
    });
  }

  // DOM helpers
  const $ = id => document.getElementById(id);
  function show(elem){ elem.classList.remove('hidden'); }
  function hide(elem){ elem.classList.add('hidden'); }

  // Startup error panel
  function showStartupError(message, canContinueWithoutOffline=false){
    const panel = $('errorPanel');
    $('errorMessage').textContent = String(message || 'Startup failed');
    const continueBtn = document.querySelector('[data-action="continue-without-offline"]');
    if (canContinueWithoutOffline) show(continueBtn); else hide(continueBtn);
    show(panel);
  }
  function hideStartupError(){ hide($('errorPanel')); }

  // Single event delegation for clicks
  document.addEventListener('click', function(evt){
    const btn = evt.target.closest('button, [data-action]');
    if (!btn) return;
    if (btn.disabled) return;
    const action = btn.dataset && btn.dataset.action;
    if (action) {
      evt.preventDefault();
      handleAction(action, evt, btn);
    }
  }, { capture: false });

  // Action handler dispatch
  async function handleAction(action, evt, el){
    if (action === 'record-visit'){
      await recordVisit();
    } else if (action === 'retry-init'){
      hideStartupError();
      initApp();
    } else if (action === 'continue-without-offline'){
      hideStartupError();
      // user accepts limited offline behavior (we already started without SW offline capability)
    }
  }

  // UI update helpers
  function setCount(n){ $('visitCount').textContent = Number.isFinite(n) ? String(n) : '—'; }
  function setTs(ts){ $('visitTs').textContent = ts ? new Date(ts).toLocaleString() : '—'; }
  function setOffline(flag){ const el = $('offlineIndicator'); if (flag) show(el); else hide(el); }

  // API helpers
  async function apiGetVisit(){
    try {
      const resp = await fetch('/api/visit');
      if (!resp.ok) throw new Error('network');
      const data = await resp.json();
      return data;
    } catch(err){ throw err; }
  }
  async function apiPostVisit(){
    try {
      const resp = await fetch('/api/visit', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
      if (!resp.ok) throw new Error('network');
      const data = await resp.json();
      return data;
    } catch(err){ throw err; }
  }

  // Record visit flow
  async function recordVisit(){
    const btn = $('recordBtn');
    btn.disabled = true;
    try {
      const data = await apiPostVisit();
      setOffline(false);
      setCount(data.count);
      setTs(data.ts);
      try { safeStorage.setItem('lastCount', String(data.count)); safeStorage.setItem('lastTs', data.ts); } catch(e){}
    } catch(err){
      // If offline, try local cache
      const cached = safeStorage.getItem('lastCount');
      if (cached !== null) setCount(Number(cached));
      setOffline(true);
    } finally{
      btn.disabled = false;
    }
  }

  // Init sequence on DOMContentLoaded
  async function initApp(){
    try {
      // 1) Try to open optional IndexedDB but don't fail init on error
      try { await tryOpenIndexedDB().catch(()=>{}); } catch(e){}

      // 2) Fetch current visit count
      try {
        const data = await apiGetVisit();
        setOffline(false);
        setCount(data.count);
        setTs(data.ts);
        try { safeStorage.setItem('lastCount', String(data.count)); safeStorage.setItem('lastTs', data.ts); } catch(e){}
      } catch(err) {
        // server unreachable: show cached value and offline indicator
        const cached = safeStorage.getItem('lastCount');
        const cachedTs = safeStorage.getItem('lastTs');
        if (cached !== null) setCount(Number(cached)); else setCount(null);
        setTs(cachedTs || null);
        setOffline(true);
      }

    } catch (err) {
      console.error('Initialization failed');
      showStartupError('Initialization failed. Please Retry.');
    }
  }

  // Initialization entry point guarded on DOMContentLoaded
  document.addEventListener('DOMContentLoaded', () => {
    (async () => {
      try {
        await initApp();
      } catch (err) {
        console.error('Startup error');
        showStartupError('Startup error. Please Retry.');
      }

      // After app init, attempt to register service worker (non-blocking and non-fatal)
      try {
        if (window.isSecureContext && 'serviceWorker' in navigator && location.protocol !== 'file:' && location.protocol !== 'content:'){
          navigator.serviceWorker.register('/sw.js').then(() => {
            console.log('Service worker registered');
          }).catch(err => {
            console.warn('Service worker registration failed');
            // Show a minimal panel allowing the user to continue without offline mode
            showStartupError('Service worker failed to register. You may continue without offline mode.', true);
          });
        }
      } catch (err) {
        console.warn('Service worker registration attempt threw', err && err.message);
        showStartupError('Service worker failed to register. You may continue without offline mode.', true);
      }
    })();
  });
})();

