// Simple test that starts the server on a random port, POSTs /api/visit and asserts the response contains a numeric count >= 1
const assert = require('assert');
const { startServer } = require('../server');
const http = require('http');

(async () => {
  let serverObj;
  try {
    serverObj = await startServer({ port: 0 });
    const port = serverObj.port;

    await new Promise((resolve, reject) => {
      const data = JSON.stringify({});
      const opts = {
        hostname: '127.0.0.1',
        port,
        path: '/api/visit',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(data)
        }
      };

      const req = http.request(opts, res => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', chunk => body += chunk);
        res.on('end', () => {
          try {
            assert.equal(res.statusCode >= 200 && res.statusCode < 300, true, 'Expected 2xx response');
            const parsed = JSON.parse(body);
            assert(parsed && typeof parsed.count === 'number', 'Response must contain numeric count');
            assert(parsed.count >= 1, 'Count must be >= 1');
            resolve();
          } catch (err) { reject(err); }
        });
      });
      req.on('error', reject);
      req.write(data);
      req.end();
    });

    console.log('Test passed: POST /api/visit returned numeric count >= 1');
  } catch (err) {
    console.error('Test failed:', err && err.message);
    process.exitCode = 2;
  } finally {
    if (serverObj && serverObj.stop) {
      try { await serverObj.stop(); } catch(e){}
    }
  }
})();

