// Simple build step: copy public/ into dist/ for deployment (node-based copy to remain cross-platform)
const fs = require('fs');
const path = require('path');

function copyRecursive(src, dest) {
  if (!fs.existsSync(src)) return;
  const stat = fs.statSync(src);
  if (stat.isDirectory()){
    if (!fs.existsSync(dest)) fs.mkdirSync(dest, { recursive: true });
    const entries = fs.readdirSync(src);
    for (const e of entries) copyRecursive(path.join(src,e), path.join(dest,e));
  } else {
    fs.copyFileSync(src, dest);
  }
}

const src = path.join(__dirname, 'public');
const dest = path.join(__dirname, 'dist', 'public');
try{
  copyRecursive(src, dest);
  // also copy server.js and package.json to dist root
  const rootDest = path.join(__dirname, 'dist');
  fs.copyFileSync(path.join(__dirname, 'server.js'), path.join(rootDest, 'server.js'));
  fs.copyFileSync(path.join(__dirname, 'package.json'), path.join(rootDest, 'package.json'));
  console.log('Build complete. dist/ created.');
} catch(err){
  console.error('Build failed:', err && err.message);
  process.exit(1);
}
